-- Exact selected account-month totals, flags and demo priority. Account suffix is numeric. Use this for all account totals; the capped evidence list is not a totals source.
SELECT * FROM finance.agent_demo_fs.account_risk_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY') AND period_key = CASE WHEN CAST({{period_key}} AS INT) = 0 THEN (SELECT MAX(period_key) FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY')) ELSE CAST({{period_key}} AS INT) END AND account_id = CONCAT('ACC', LPAD(CAST(CAST({{account_number}} AS BIGINT) AS STRING), 8, '0')) LIMIT 1
